631	\section{Formalization support for finite sampling}
632	
633	The following finite-distribution identities are not named statements of the
634	source article.  They make explicit the push-forward calculations used in the
635	low-degree question and line-point laws above.
636	
637	\begin{lemma}[Extensionality of finite distributions]\label{lem:distribution-ext-support}
638		\lean{MIPStarRE.QPBT.Distribution.ext_of_support_of_weight}
639		\leanok
640		Two finite distributions with the same support and the same weight at every
641		point are equal.
642	\end{lemma}
643	\begin{proof}
644		\leanok
645		The two laws have the same finite support and assign the same mass to every
646		point, so they coincide.
647	\end{proof}
648	
649	\begin{lemma}[Composition of push-forwards]\label{lem:distribution-map-comp}
650		\lean{MIPStarRE.QPBT.Distribution.map_map}
651		\leanok
652		Let $\mu$ be a finite distribution on $A$, and let $e\colon A\to B$ and
653		$f\colon B\to C$. Then
654		\[
655			f_\ast(e_\ast\mu)=(f\circ e)_\ast\mu.
656		\]
657	\end{lemma}
658	\begin{proof}
659		\leanok
660		\uses{lem:distribution-ext-support}
661		The supports agree by composition of finite images.  For each $c\in C$,
662		partition the fiber of $f\circ e$ over $c$ by the intermediate value $e(a)$;
663		the corresponding sums of weights agree.
664	\end{proof}
665	
666	\begin{lemma}[Weights of the uniform law]\label{lem:uniform-distribution-weight}
667		\lean{MIPStarRE.QPBT.uniformDistribution_weight_apply}
668		\leanok
669		If $A$ is a nonempty finite set, then its uniform distribution assigns weight
670		$1/|A|$ to every $a\in A$.
671	\end{lemma}
672	\begin{proof}
673		\leanok
674		This is the defining weight of the uniform distribution on a nonempty finite
675		set.
676	\end{proof}
677	
678	\begin{lemma}[Uniform push-forward along a balanced map]\label{lem:uniform-map-equal-fibers}
679		\lean{MIPStarRE.QPBT.uniformDistribution_map_of_card_fiber}
680		\leanok
681		Let $A$ and $B$ be nonempty finite sets and let $e\colon A\to B$. If there is
682		an integer $c$ such that $|e^{-1}(b)|=c$ for every $b\in B$, then
683		$e_\ast\operatorname{Unif}(A)=\operatorname{Unif}(B)$.
684	\end{lemma}
685	\begin{proof}
686		\leanok
687		\uses{lem:distribution-ext-support, lem:uniform-distribution-weight}
688		Every fiber is nonempty, so $e$ is surjective and both supports are $B$.
689		Counting the fibers gives $|A|=c|B|$; summing the weight $1/|A|$ over a
690		$c$-element fiber gives $1/|B|$.
691	\end{proof}
692	
693	\begin{lemma}[Uniformity under an equivalence]\label{lem:uniform-map-equivalence}
694		\lean{MIPStarRE.QPBT.uniformDistribution_map_equiv}
695		\leanok
696		An equivalence $E\colon A\simeq B$ between nonempty finite sets satisfies
697		$E_\ast\operatorname{Unif}(A)=\operatorname{Unif}(B)$.
698	\end{lemma}
699	\begin{proof}
700		\leanok
701		\uses{lem:uniform-map-equal-fibers}
702		Every fiber of an equivalence has cardinality one, so the result follows from
703		Lemma~\ref{lem:uniform-map-equal-fibers}.
704	\end{proof}
705	
706	\begin{lemma}[First marginal of a uniform product]\label{lem:uniform-product-first-marginal}
707		\lean{MIPStarRE.QPBT.uniformDistribution_map_fst}
708		\leanok
709		For nonempty finite sets $A$ and $B$, the first marginal of
710		$\operatorname{Unif}(A\times B)$ is $\operatorname{Unif}(A)$.
711	\end{lemma}
712	\begin{proof}
713		\leanok
714		\uses{lem:uniform-map-equal-fibers}
715		Every fiber of the first projection has cardinality $|B|$; apply
716		Lemma~\ref{lem:uniform-map-equal-fibers}.
717	\end{proof}
718	
719	\begin{lemma}[Second marginal of a uniform product]\label{lem:uniform-product-second-marginal}
720		\lean{MIPStarRE.QPBT.uniformDistribution_map_snd}
721		\leanok
722		For nonempty finite sets $A$ and $B$, the second marginal of
723		$\operatorname{Unif}(A\times B)$ is $\operatorname{Unif}(B)$.
724	\end{lemma}
725	\begin{proof}
726		\leanok
727		\uses{lem:uniform-map-equal-fibers}
728		Every fiber of the second projection has cardinality $|A|$; apply
729		Lemma~\ref{lem:uniform-map-equal-fibers}.
730	\end{proof}
731	
732	\begin{lemma}[Dependent uniform sampling as a product push-forward]\label{lem:uniform-bind-map}
733		\lean{MIPStarRE.QPBT.bind_uniformDistribution_map}
734		\leanok
735		Let $A$ and $B$ be nonempty finite sets and let $g\colon A\to B\to C$.
736		Sampling $a$ uniformly from $A$, then $b$ uniformly from $B$, and returning
737		$g(a,b)$ has the same law as pushing $\operatorname{Unif}(A\times B)$ forward
738		along $(a,b)\mapsto g(a,b)$.
739	\end{lemma}
740	\begin{proof}
741		\leanok
742		\uses{lem:distribution-ext-support, lem:uniform-distribution-weight}
743		Both supports are the image of $A\times B$ under $g$.  At each $c\in C$,
744		both weights are the number of pairs $(a,b)$ with $g(a,b)=c$, divided by
745		$|A||B|$.
746	\end{proof}
747	
748	\begin{lemma}[Uniform first marginal after an equivalence]
749		\label{lem:uniform-first-marginal-after-equivalence}
750		\lean{MIPStarRE.QPBT.uniformDistribution_map_fst_of_equiv}
751		\leanok
752		Let $A$, $B$, and $C$ be nonempty finite sets, let $E\colon A\simeq B\times C$,
753		and suppose $f(a)$ is the first component of $E(a)$ for every $a\in A$. Then
754		$f_\ast\operatorname{Unif}(A)=\operatorname{Unif}(B)$.
755	\end{lemma}

